arguments.command:
cd /app && python3 -c "
import torch
w=torch.load('weights.pt',map_location='cpu')
print(type(w))
for k,v in w.items():
    print(k, tuple(v.shape) if hasattr(v,'shape') else v)
print('---dataset---')
d=torch.load('dataset.pt',map_location='cpu')
print(type(d))
if isinstance(d,dict):
    for k,v in d.items(): print(k, type(v), getattr(v,'shape',None))
else:
    print(len(d) if hasattr(d,'__len__') else d)
    for x in (d if isinstance(d,(list,tuple)) else []): print(type(x),getattr(x,'shape',None))
"

